def test_incomplete_inventory_identity_appears_and_clears(self) -> None:
    # ACTUAL snapshot-level identity: without ``process_snapshot_complete``
    # the merge reports ``process-provider:incomplete`` (error); marking the
    # snapshot complete removes that identity -- the "cleared" pattern
    # applied at snapshot scope rather than lane scope.
    incomplete = {"lanes": SNAPSHOT_L1_L2["lanes"]}
    result = merge_watcher_conditions(incomplete)
    self.assertIn("process-provider:incomplete", result)
    self.assertEqual(
        "PROCESS_INVENTORY_INCOMPLETE", result["process-provider:incomplete"]["type"]
    )
    self.assertEqual("error", result["process-provider:incomplete"]["severity"])

    complete = {"lanes": SNAPSHOT_L1_L2["lanes"], "process_snapshot_complete": True}
    cleared = merge_watcher_conditions(complete)
    self.assertNotIn("process-provider:incomplete", cleared)
    self.assertIn("lane:L1:process", cleared)

